// G001: raw DNA files from consumer services, read offline. The files below
// are synthetic and follow the vendors' layouts; nothing here is a real
// genome.
import 'package:flutter_test/flutter_test.dart';
import 'package:human_health_os/src/domain/genetics/raw_genome.dart';

const twentyThreeAndMe =
    '''# This data file generated by 23andMe at: Sat Nov 07 10:00:00 2026
#
# We are using reference human assembly build 37 (also known as Annotation Release 104).
#
# rsid\tchromosome\tposition\tgenotype
rs100\t1\t1000\tAG
rs101\t1\t2000\t--
rs102\t2\t3000\tDD
rs103\t22\t4000\tCC
rs104\tX\t5000\tA
rs105\tY\t6000\t--
rs106\tMT\t7000\tG
i7001\t3\t8000\tII
''';

const ancestry = '''#AncestryDNA raw data download
#This file was generated by AncestryDNA at: 11/07/2026 10:00:00 MST
#Data was collected using AncestryDNA array version: V2.0
#Genetic data is provided below as five TAB delimited columns.  Each line corresponds to a SNP.  Columns two and three contain the chromosome and basepair position of the SNP using human reference build 37.1 coordinates.
rsid\tchromosome\tposition\tallele1\tallele2
rs100\t1\t1000\tA\tG
rs101\t1\t2000\t0\t0
rs102\t23\t3000\tC\tC
rs103\t24\t4000\t0\t0
rs104\t25\t5000\tT\tT
rs105\t26\t6000\tG\tG
rs106\t2\t7000\tD\tI
''';

const myHeritage = '''##fileformat=MyHeritage
# MyHeritage DNA raw data.
# This file was generated on 2026-11-07 10:00:00
# build 37
RSID,CHROMOSOME,POSITION,RESULT
"rs100","1","1000","AG"
"rs101","1","2000","--"
"rs102","X","3000","A"
"rs103","MT","4000","GG"
''';

const familyTreeDna = '''RSID,CHROMOSOME,POSITION,RESULT
"rs100","1","1000","AG"
"rs101","1","2000","--"
"rs102","M","3000","C"
''';

/// [n] valid lines (so that a few bad ones do not make the file mostly bad).
String filler(int n) {
  final rows = [for (var i = 0; i < n; i++) 'rsF$i\t1\t${i + 1}\tAA'];
  return '${rows.join('\n')}\n';
}

void main() {
  group('the four layouts', () {
    test('23andMe: tab separated, header in a comment, build 37', () {
      final g = parseRawGenome(twentyThreeAndMe);
      expect(g.source, GenomeSource.twentyThreeAndMe);
      expect(g.vendorHint, '23andMe');
      expect(g.build, '37');
      expect(g.headerLines.length, 5);
      expect(g.total, 8);
      expect(g.noCallCount, 2);
      expect(g.calledCount, 6);
      expect(g.invalidCount, 0);
      expect(g.variants.first.rsid, 'rs100');
      expect(g.variants.first.call, 'AG');
      expect(g.variants[2].call, 'DD', reason: 'indel markers as typed');
      expect(g.variants[4].call, 'A', reason: 'a single base on X');
      expect(g.variants.last.rsid, 'i7001');
    });

    test('AncestryDNA: five columns, 23-26 are X, Y, XY and MT', () {
      final g = parseRawGenome(ancestry);
      expect(g.source, GenomeSource.ancestryDna);
      expect(g.vendorHint, 'AncestryDNA');
      expect(g.build, '37');
      expect(g.total, 7);
      expect(
        [for (final v in g.variants) v.chromosome],
        ['1', '1', 'X', 'Y', 'XY', 'MT', '2'],
      );
      expect(g.variants[0].call, 'AG', reason: 'two alleles joined');
      expect(g.variants[1].call, isNull, reason: '0 and 0 is a no-call');
      expect(g.variants[3].call, isNull);
      expect(g.variants.last.call, 'DI');
    });

    test('MyHeritage: quoted CSV with comments', () {
      final g = parseRawGenome(myHeritage);
      expect(g.source, GenomeSource.csv);
      expect(g.vendorHint, 'MyHeritage');
      expect(g.build, '37');
      expect(g.total, 4);
      expect(g.variants[1].call, isNull);
      expect(g.variants[2].call, 'A');
      expect(g.variants.last.chromosome, 'MT');
    });

    test('FamilyTreeDNA: the same CSV without comments, M is MT', () {
      final g = parseRawGenome(familyTreeDna);
      expect(g.source, GenomeSource.csv);
      expect(g.vendorHint, isNull);
      expect(
        g.build,
        isNull,
        reason: 'a file that says nothing is not guessed',
      );
      expect(g.total, 3);
      expect(g.variants.last.chromosome, 'MT');
    });

    test('Windows line endings, a byte order mark and lower case are read', () {
      final crlf = '﻿${twentyThreeAndMe.replaceAll('\n', '\r\n')}'.replaceFirst(
        'rs100\t1\t1000\tAG',
        'rs100\t1\t1000\tag',
      );
      final g = parseRawGenome(crlf);
      expect(g.total, 8);
      expect(g.invalidCount, 0);
      expect(g.variants.first.call, 'AG');
    });

    test('a file without any comment header is still recognised by shape', () {
      final tab4 = parseRawGenome('rs1\t1\t10\tAA\nrs2\t2\t20\tCC\n');
      expect(tab4.source, GenomeSource.twentyThreeAndMe);
      final tab5 = parseRawGenome('rs1\t1\t10\tA\tA\nrs2\t2\t20\tC\tC\n');
      expect(tab5.source, GenomeSource.ancestryDna);
      final csv = parseRawGenome('"rs1","1","10","AA"\n"rs2","2","20","CC"\n');
      expect(csv.source, GenomeSource.csv);
    });
  });

  group('missing is not reference; nothing is dropped silently', () {
    test('no-calls stay no-calls in every spelling', () {
      for (final nc in ['--', '-', '0', '00', '']) {
        final g = parseRawGenome('rs1\t1\t10\t$nc\nrs2\t1\t20\tAA\n');
        expect(g.variants.first.isCalled, isFalse, reason: 'spelled "$nc"');
        expect(g.variants.first.call, isNull);
        expect(g.noCallCount, 1);
      }
    });

    test('one allele read and one not is not a call', () {
      final rows = [for (var i = 0; i < 10; i++) 'rsF$i\t1\t${i + 1}\tA\tA']
          .join('\n');
      final g = parseRawGenome(
        'rsid\tchromosome\tposition\tallele1\tallele2\n$rows\nrs1\t1\t10\tA\t0\n',
      );
      expect(g.total, 10);
      expect(g.invalidCount, 1);
      expect(g.invalidSample.single.reason, 'PARTIAL');
    });

    test('unreadable lines are counted with their line numbers, the first '
        '20 kept', () {
      final lines = StringBuffer(filler(200));
      for (var i = 0; i < 30; i++) {
        lines.writeln('rsX$i\t1\t$i'); // wrong column count
      }
      lines
        ..writeln('rsA\t99\t5\tAA')
        ..writeln('rsB\t1\tnotanumber\tAA')
        ..writeln('rsC\t1\t5\tXZ')
        ..writeln('r s\t1\t5\tAA')
        ..writeln('rs9\t1\t6\tCC');
      final g = parseRawGenome(lines.toString());
      expect(g.total, 201);
      expect(g.invalidCount, 34);
      expect(g.invalidSample, hasLength(20));
      expect(g.invalidSample.first.lineNumber, 201);
      expect(g.invalidSample.first.reason, 'COLUMNS');
      final all = parseRawGenome(
        '${filler(30)}rsA\t99\t5\tAA\nrsB\t1\tx\tAA\nrsC\t1\t5\tXZ\nr s\t1\t5\tAA\n',
      );
      expect(
        [for (final i in all.invalidSample) (i.lineNumber, i.reason)],
        [(31, 'CHROMOSOME'), (32, 'POSITION'), (33, 'GENOTYPE'), (34, 'ID')],
      );
    });

    test('duplicate ids are counted and kept', () {
      final g = parseRawGenome(
        'rs1\t1\t10\tAA\nrs1\t1\t10\tAA\nrs2\t1\t20\tCC\nrs1\t1\t10\tAG\n',
      );
      expect(g.total, 4);
      expect(g.duplicateCount, 2);
    });
  });

  group('refusals', () {
    test('empty, unknown, header-only and binary-looking files are refused '
        'with a code', () {
      for (final (text, code) in [
        ('', 'EMPTY'),
        ('   \n\n', 'EMPTY'),
        ('hello world\nthis is not dna', 'UNKNOWN_FORMAT'),
        ('{"a": 1}', 'UNKNOWN_FORMAT'),
        (
          '# only comments\n# rsid chromosome position genotype\n',
          'UNKNOWN_FORMAT',
        ),
        ('rsid\tchromosome\tposition\tgenotype\n', 'NO_VARIANTS'),
        ('RSID,CHROMOSOME,POSITION,RESULT\n', 'NO_VARIANTS'),
        ('rs1\t99\t5\tAA\n', 'NO_VARIANTS'),
        ('\u0000\u0001\u0002\u0003', 'UNKNOWN_FORMAT'),
      ]) {
        expect(
          () => parseRawGenome(text),
          throwsA(isA<GenomeFormatError>().having((e) => e.code, 'code', code)),
          reason: text.replaceAll('\n', '|'),
        );
      }
    });
  });

  group('refusals before parsing (bytes)', () {
    GenomeFormatError? refused(List<int> b) {
      try {
        parseRawGenomeBytes(b);
      } on GenomeFormatError catch (e) {
        return e;
      }
      return null;
    }

    test('archives, UTF-16, VCF, binary and oversized files are refused by '
        'content, not by name', () {
      expect(refused([0x1F, 0x8B, 8, 0, 0])!.code, 'COMPRESSED');
      expect(refused([0x50, 0x4B, 3, 4])!.code, 'COMPRESSED');
      expect(refused([0xFF, 0xFE, 0x72, 0x00])!.code, 'NOT_TEXT');
      expect(refused([0xFE, 0xFF, 0x00, 0x72])!.code, 'NOT_TEXT');
      expect(
        refused('##fileformat=VCFv4.2\n#CHROM\tPOS'.codeUnits)!.code,
        'VCF',
      );
      expect(refused([0x72, 0x73, 0x00, 0x31])!.code, 'NOT_TEXT');
      expect(refused(const [])!.code, 'EMPTY');
      expect(
        refused(List<int>.filled(maxRawGenomeBytes + 1, 0x41))!.code,
        'TOO_LARGE',
      );
    });

    test('a good file is read from bytes, malformed UTF-8 is an unreadable '
        'line, not another genotype', () {
      final ok = parseRawGenomeBytes(twentyThreeAndMe.codeUnits);
      expect(ok.total, 8);
      final bytes = [
        ...filler(30).codeUnits,
        ...'rsBad\t1\t5\t'.codeUnits,
        0xC3,
        0x28,
        ...'\n'.codeUnits,
      ];
      final g = parseRawGenomeBytes(bytes);
      expect(g.total, 30);
      expect(g.invalidCount, 1);
    });

    test('a file that is mostly unreadable is refused whole', () {
      final text = StringBuffer(filler(10));
      for (var i = 0; i < 10; i++) {
        text.writeln('junk line $i');
      }
      expect(
        () => parseRawGenome(text.toString()),
        throwsA(
          isA<GenomeFormatError>().having(
            (e) => e.code,
            'code',
            'MOSTLY_INVALID',
          ),
        ),
      );
    });

    test('errors carry a code and a line number, never the text of a line', () {
      final g = parseRawGenome('${filler(20)}rsSECRET\t1\t5\tZZ\n');
      for (final i in g.invalidSample) {
        expect('${i.reason} ${i.lineNumber}', isNot(contains('SECRET')));
      }
      for (final e in const [
        GenomeFormatError('UNKNOWN_FORMAT'),
        GenomeFormatError('MOSTLY_INVALID'),
      ]) {
        expect(
          e.toString(),
          matches(RegExp(r'^GenomeFormatError\([A-Z_]+\)$')),
        );
      }
    });
  });

  group('summary', () {
    test('per-chromosome counts come in the order 1-22, X, Y, XY, MT', () {
      final g = parseRawGenome(twentyThreeAndMe);
      expect(g.perChromosome.keys.toList(), [
        '1',
        '2',
        '3',
        '22',
        'X',
        'Y',
        'MT',
      ]);
      expect(g.perChromosome['1'], 2);
    });

    test('a file of 700,000 lines is read in a few seconds', () {
      final b = StringBuffer('# rsid\tchromosome\tposition\tgenotype\n');
      const bases = ['AA', 'AG', 'GG', 'CT', '--', 'TT'];
      for (var i = 0; i < 700000; i++) {
        b.writeln('rs$i\t${(i % 22) + 1}\t${i * 7}\t${bases[i % 6]}');
      }
      final text = b.toString();
      final watch = Stopwatch()..start();
      final g = parseRawGenome(text);
      watch.stop();
      expect(g.total, 700000);
      expect(g.noCallCount, 116666, reason: 'one in six is "--"');
      expect(watch.elapsed.inSeconds, lessThan(15));
    });
  });
}
